// UpsertV2 inserts or updates a 2 record with domain-specific columns.
func (s *Store) UpsertV2(data json.RawMessage) error {
	var obj map[string]any
	if err := json.Unmarshal(data, &obj); err != nil {
		return fmt.Errorf("unmarshaling 2: %w", err)
	}

	id := extractObjectID(obj)
	if id == "" {
		return fmt.Errorf("missing id for 2")
	}

	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := s.upsertGenericResourceTx(tx, "2", id, data); err != nil {
		return err
	}
	if err := s.upsertV2Tx(tx, id, obj, data); err != nil {
		return err
	}

	return tx.Commit()
}

// UpsertBatch inserts or replaces multiple records in a single transaction
// and returns the count of items actually stored. This is 10-100x faster
// than individual Upsert calls for bulk operations.
//
// The returned count lets sync log the honest stored-row count rather
// than the consumed-item count. When the API returns scalar IDs rather
// than objects (Firebase /topstories.json, GitHub user-repo lists, etc.)
// every item fails ID extraction and stored=0 even when consumed=N —
// callers can detect this divergence and warn loudly instead of
// silently reporting "N synced".
//
// For resource types that have a domain-specific typed table, the per-item
// generic insert is followed by a dispatch to the matching upsert<Pascal>Tx
// inside the same transaction. Without that dispatch, paginated syncs would
// only populate the generic resources table — typed tables (and indexed
// columns like parent_id added by dependent-resource sync) would stay empty.
func (s *Store) UpsertBatch(resourceType string, items []json.RawMessage) (int, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, fmt.Errorf("starting batch transaction: %w", err)
	}
	defer tx.Rollback()

	var stored, skippedCount int
	for _, item := range items {
		var obj map[string]any
		if err := json.Unmarshal(item, &obj); err != nil {
			skippedCount++
			continue
		}
		// Try common primary key field names in priority order.
		var id string
		for _, key := range []string{"id", "ID", "ticker", "event_ticker", "series_ticker", "key", "code", "uid", "uuid", "slug", "name"} {
			if v := lookupFieldValue(obj, key); v != nil {
				s := fmt.Sprintf("%v", v)
				if s != "" && s != "<nil>" {
					id = s
					break
				}
			}
		}
		if id == "" {
			skippedCount++
			continue
		}

		if err := s.upsertGenericResourceTx(tx, resourceType, id, item); err != nil {
			return 0, fmt.Errorf("upserting %s/%s: %w", resourceType, id, err)
		}

		switch resourceType {
		case "community_about_timeline":
			if err := s.upsertCommunityAboutTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "create_bookmark":
			if err := s.upsertCreateBookmarkTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "followers":
			if err := s.upsertFollowersTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "followers_you_know":
			if err := s.upsertFollowersYouKnowTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "user_tweets":
			if err := s.upsertUserTweetsTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "create_tweet":
			if err := s.upsertCreateTweetTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "retweeters":
			if err := s.upsertRetweetersTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "tweet_detail":
			if err := s.upsertTweetDetailTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "tweet_result_by_rest_id":
			if err := s.upsertTweetResultByRestIdTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "user_tweets_and_replies":
			if err := s.upsertUserTweetsAndRepliesTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "delete_bookmark":
			if err := s.upsertDeleteBookmarkTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "notifications_timeline":
			if err := s.upsertNotificationsTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "search_timeline":
			if err := s.upsertSearchTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "user_by_screen_name":
			if err := s.upsertUserByScreenNameTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "bookmarks":
			if err := s.upsertBookmarksTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "community_media_timeline":
			if err := s.upsertCommunityMediaTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "favorite_tweet":
			if err := s.upsertFavoriteTweetTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "home_timeline":
			if err := s.upsertHomeTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "create_retweet":
			if err := s.upsertCreateRetweetTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "following":
			if err := s.upsertFollowingTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "user_highlights_tweets":
			if err := s.upsertUserHighlightsTweetsTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "user_media":
			if err := s.upsertUserMediaTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "favoriters":
			if err := s.upsertFavoritersTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "likes":
			if err := s.upsertLikesTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "user_by_rest_id":
			if err := s.upsertUserByRestIdTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "community_tweets_timeline":
			if err := s.upsertCommunityTweetsTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "profile_spotlights_query":
			if err := s.upsertProfileSpotlightsQueryTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "unfavorite_tweet":
			if err := s.upsertUnfavoriteTweetTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "delete_retweet":
			if err := s.upsertDeleteRetweetTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "delete_tweet":
			if err := s.upsertDeleteTweetTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "home_latest_timeline":
			if err := s.upsertHomeLatestTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "list_latest_tweets_timeline":
			if err := s.upsertListLatestTweetsTimelineTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "users_by_rest_ids":
			if err := s.upsertUsersByRestIdsTx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "1_1":
			if err := s.upsertV11Tx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		case "2":
			if err := s.upsertV2Tx(tx, id, obj, item); err != nil {
				return 0, fmt.Errorf("typed upsert for %s/%s: %w", resourceType, id, err)
			}
		}
		stored++
	}

	// Warn when most items in a batch lack an extractable ID — this likely
	// means the API uses a primary key field we don't recognize yet.
	if skippedCount > 0 && len(items) > 0 && skippedCount*2 > len(items) {
		fmt.Fprintf(os.Stderr, "warning: %d/%d %s items skipped (no extractable ID field found)\n", skippedCount, len(items), resourceType)
	}

	if err := tx.Commit(); err != nil {
		return 0, err
	}
	return stored, nil
}

func (s *Store) SaveSyncState(resourceType, cursor string, count int) error {
	_, err := s.db.Exec(
		`INSERT INTO sync_state (resource_type, last_cursor, last_synced_at, total_count)
		 VALUES (?, ?, ?, ?)
		 ON CONFLICT(resource_type) DO UPDATE SET last_cursor = excluded.last_cursor,
		 last_synced_at = excluded.last_synced_at, total_count = excluded.total_count`,
		resourceType, cursor, time.Now(), count,
	)
	return err
}

func (s *Store) GetSyncState(resourceType string) (cursor string, lastSynced time.Time, count int, err error) {
	err = s.db.QueryRow(
		`SELECT last_cursor, last_synced_at, total_count FROM sync_state WHERE resource_type = ?`,
		resourceType,
	).Scan(&cursor, &lastSynced, &count)
	if err == sql.ErrNoRows {
		return "", time.Time{}, 0, nil
	}
	return
}

// SaveSyncCursor stores the pagination cursor for a resource type.
func (s *Store) SaveSyncCursor(resourceType, cursor string) error {
	_, err := s.db.Exec(
		`INSERT INTO sync_state (resource_type, last_cursor, last_synced_at, total_count)
		 VALUES (?, ?, CURRENT_TIMESTAMP, 0)
		 ON CONFLICT(resource_type) DO UPDATE SET last_cursor = ?, last_synced_at = CURRENT_TIMESTAMP`,
		resourceType, cursor, cursor,
	)
	return err
}

// GetSyncCursor returns the last pagination cursor for a resource type.
func (s *Store) GetSyncCursor(resourceType string) string {
	var cursor sql.NullString
	s.db.QueryRow("SELECT last_cursor FROM sync_state WHERE resource_type = ?", resourceType).Scan(&cursor)
	if cursor.Valid {
		return cursor.String
	}
	return ""
}

// ListIDs returns all IDs from a resource's domain table, or from the generic
// resources table if no domain table exists. Used by dependent sync to iterate parents.
func (s *Store) ListIDs(resourceType string) ([]string, error) {
	// Try domain table first (tables are named after the resource type)
	query := fmt.Sprintf("SELECT id FROM %s", resourceType)
	rows, err := s.db.Query(query)
	if err != nil {
		// Fall back to generic resources table
		rows, err = s.db.Query("SELECT id FROM resources WHERE resource_type = ?", resourceType)
		if err != nil {
			return nil, err
		}
	}
	defer rows.Close()

	var ids []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			continue
		}
		ids = append(ids, id)
	}
	return ids, rows.Err()
}

// GetLastSyncedAt returns the last sync timestamp for a resource type.
func (s *Store) GetLastSyncedAt(resourceType string) string {
	var ts sql.NullString
	s.db.QueryRow("SELECT last_synced_at FROM sync_state WHERE resource_type = ?", resourceType).Scan(&ts)
	if ts.Valid {
		return ts.String
	}
	return ""
}

// ClearSyncCursors resets all sync state for a full resync.
func (s *Store) ClearSyncCursors() error {
	_, err := s.db.Exec("DELETE FROM sync_state")
	return err
}

// Query executes a raw SQL query and returns the rows.
// Used by workflow commands that need custom queries against the local store.
func (s *Store) Query(query string, args ...any) (*sql.Rows, error) {
	return s.db.Query(query, args...)
}

func (s *Store) Count(resourceType string) (int, error) {
	var count int
	err := s.db.QueryRow(
		`SELECT COUNT(*) FROM resources WHERE resource_type = ?`,
		resourceType,
	).Scan(&count)
	return count, err
}

func (s *Store) Status() (map[string]int, error) {
	rows, err := s.db.Query(
		`SELECT resource_type, COUNT(*) FROM resources GROUP BY resource_type ORDER BY resource_type`,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	status := make(map[string]int)
	for rows.Next() {
		var rt string
		var count int
		if err := rows.Scan(&rt, &count); err != nil {
			return nil, err
		}
		status[rt] = count
	}
	return status, rows.Err()
}

// ResolveByName resolves a human-readable name to a UUID from synced data.
// If the input is already a UUID, it is returned as-is.
// matchFields are JSON field names to search against (e.g., "name", "key", "email").
func (s *Store) ResolveByName(resourceType string, input string, matchFields ...string) (string, error) {
	if IsUUID(input) {
		return input, nil
	}

	var matches []string
	for _, field := range matchFields {
		query := fmt.Sprintf(
			`SELECT id FROM resources WHERE resource_type = ? AND LOWER(json_extract(data, '$.%s')) = LOWER(?)`,
			field,
		)
		rows, err := s.db.Query(query, resourceType, input)
		if err != nil {
			continue
		}
		for rows.Next() {
			var id string
			if rows.Scan(&id) == nil {
				// Deduplicate
				found := false
				for _, m := range matches {
					if m == id {
						found = true
						break
					}
				}
				if !found {
					matches = append(matches, id)
				}
			}
		}
		rows.Close()
	}

	switch len(matches) {
	case 0:
		return "", fmt.Errorf("%s %q not found in local store. Run 'sync' first, or use the UUID directly", resourceType, input)
	case 1:
		return matches[0], nil
	default:
		hint := matches[0]
		if len(matches) > 5 {
			hint = strings.Join(matches[:5], ", ") + "..."
		} else {
			hint = strings.Join(matches, ", ")
		}
		return "", fmt.Errorf("ambiguous: %q matches %d %s entries (%s). Use the exact UUID instead", input, len(matches), resourceType, hint)
	}
}
